const endpoint='/api/training/';
async function request<T=R>(path:string,body?:unknown,method='POST'){const resp=await fetch(endpoint+path,{method:body===undefined?'GET':method,headers:body===undefined?undefined:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store'});return readTrainingResponse<T>(resp)}
const pct=(a:number,b:number)=>b>0?Math.round(100*a/b):0;
const photo=(n:string)=>'/training-media/'+n+'.webp';
const images={hero:'home_executivo_cidade_1920x900',login:'login_retrato_executiva_900x1200',office:'escritorio_notebook_1280x720',data:'dados_grafico_1280x720',process:'processos_arquitetura_1280x720',leadership:'lideranca_duas_executivas_1280x720',strategy:'estrategia_reuniao_1280x720',portrait:'reflexao_executiva_1280x720',lesson:'aula_concreto_1280x720'};
function cover(label:string,index=0){const t=label.toLowerCase();return photo(/dado|power|intelig|bi/.test(t)?images.data:/process|oper|produção/.test(t)?images.process:/lider|equipe|pessoa/.test(t)?images.leadership:/estratég|planej|gestão/.test(t)?images.strategy:/marketing|comunic/.test(t)?images.office:/ia|chatgpt|tecnologia/.test(t)?images.portrait:[images.office,images.data,images.strategy,images.process][index%4])}
function Img({src,alt='',className=''}:{src:string,alt?:string,className?:string}){const [failed,setFailed]=useState(false);useEffect(()=>setFailed(false),[src]);return <div className={'ev-photo '+className}>{!failed&&<img src={src} alt={alt} onError={()=>setFailed(true)}/>}</div>}
function Brand(){return <span className="ev-brand"><img src="/brand/evolu-white.png" alt="EVOLU"/><small>Training</small></span>}
